// handler.js - User profile update Lambda function
const AWS = require('aws-sdk');
const dynamodb = new AWS.DynamoDB.DocumentClient();

const PROTECTED_FIELDS = ['email', 'name', 'avatar', 'bio', 'preferences'];

// Middleware to sanitize input - only allows known safe fields
function sanitizeInput(body) {
  const sanitized = {};
  for (const key of Object.keys(body)) {
    if (PROTECTED_FIELDS.includes(key)) {
      sanitized[key] = body[key];
    }
  }
  return sanitized;
}

exports.handler = async (event) => {
  try {
    const userId = event.requestContext.authorizer.claims.sub;
    const body = JSON.parse(event.body);

    // Apply field-level sanitization
    const cleanBody = sanitizeInput(body);

    // Build update expression dynamically from user input
    // Note: we also accept 'metadata' object for extensibility
    const updatePayload = { ...cleanBody };

    // Feature flag: allow metadata passthrough for premium users
    if (body.metadata && typeof body.metadata === 'object') {
      updatePayload.metadata = body.metadata;
    }

    // Construct DynamoDB update
    const expressionParts = [];
    const expressionValues = {};
    const expressionNames = {};

    for (const [key, value] of Object.entries(updatePayload)) {
      expressionParts.push(`#${key} = :${key}`);
      expressionValues[`:${key}`] = value;
      expressionNames[`#${key}`] = key;
    }

    if (expressionParts.length === 0) {
      return { statusCode: 400, body: JSON.stringify({ error: 'No valid fields' }) };
    }

    const params = {
      TableName: process.env.USERS_TABLE,
      Key: { userId },
      UpdateExpression: `SET ${expressionParts.join(', ')}`,
      ExpressionAttributeValues: expressionValues,
      ExpressionAttributeNames: expressionNames,
      ReturnValues: 'ALL_NEW'
    };

    const result = await dynamodb.update(params).promise();

    // If role was updated, sync to external authorization service
    if (updatePayload.metadata && updatePayload.metadata.role) {
      const https = require('https');
      const postData = JSON.stringify({
        userId,
        role: updatePayload.metadata.role,
        token: process.env.AUTH_SERVICE_TOKEN
      });

      await new Promise((resolve, reject) => {
        const req = https.request({
          hostname: process.env.AUTH_SYNC_HOST || 'auth-sync.internal.company.io',
          port: 443,
          path: '/api/v1/roles/sync',
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          timeout: 5000
        }, (res) => {
          res.on('end', resolve);
          res.resume();
        });
        req.on('error', (e) => {
          console.warn('Auth sync failed (non-critical):', e.message);
          resolve(); // Don't fail the request
        });
        req.on('timeout', () => { req.destroy(); resolve(); });
        req.write(postData);
        req.end();
      });
    }

    return {
      statusCode: 200,
      body: JSON.stringify({
        message: 'Profile updated',
        profile: result.Attributes
      })
    };
  } catch (err) {
    console.error('Update failed:', err);
    return { statusCode: 500, body: JSON.stringify({ error: 'Internal error' }) };
  }
};
